# scripts/template_new.py
"""A new project is generated by task from the template on GitHub, pinned (D.54).

Copier records the source it is given as _src_path and the ref as _commit. A laptop
path recorded there breaks copier update on any other machine, and an unpinned ref
lets Copier pick its own idea of latest. So the source is the repository the identity
declaration names (D.52), the ref must be a full commit sha, and the destination must
be new and outside this repository. Python observes; policies/runs/template/new decides.

OVER SSH, NEVER WAITING: this machine reaches GitHub over SSH, and git and ssh prompt on
the terminal, so the clone runs with prompts off and a failure is reported as data (D.57).
"""

from __future__ import annotations

import os
import sys
from collections.abc import Iterator, Sequence
from contextlib import contextmanager
from pathlib import Path
from typing import ClassVar, Literal
from urllib.parse import urlsplit

from copier import run_copy
from plumbum import local

from command_outcome import announce
from contract_base import Contract
from project_identity import load
from spine import decide, enforce, evaluate, halted, reasons, refusal_code

ROOT = Path(__file__).resolve().parent.parent
ENTRYPOINT = "data.runs.template.new.deny"
COMMAND = "template:new"
SUBJECT = "template_request"
POLICY = Path(__file__).resolve().parent.parent / "policies" / "runs" / "template" / "new"
# SSH'S ACCOUNT NAME ON GITHUB. The host and path come from the declaration, and the
# address is composed, never written whole: an address literal reads as an email (D.57).
SSH_USER = "git"


class TemplateRequest(Contract):
    """template-request/v1: what would be generated, from where, and what is there."""

    CONTRACT_ID: ClassVar[str] = "template-request/v1"

    contract: Literal["template-request/v1"] = "template-request/v1"
    # WHAT COPIER RECORDS AS _src_path: HTTPS, so no user-at-host string lands in a
    # generated project's answers (D.64). The clone itself goes over transport.
    source: str
    transport: str
    ref: str
    destination: str
    destination_exists: bool
    destination_empty: bool
    inside_source: bool


def _ssh(repository: str) -> str:
    """The declared GitHub repository as the SSH URL this machine pushes with (D.57)."""
    parts = urlsplit(repository)
    return f"{SSH_USER}@{parts.netloc}:{parts.path.strip('/')}.git"


@contextmanager
def _non_interactive(rewrite: tuple[str, str] | None = None) -> Iterator[None]:
    """git and ssh fail instead of prompting, for this call only, then restored (D.57)."""
    ssh = os.environ.get("GIT_SSH_COMMAND", "ssh")
    wanted = {
        "GIT_TERMINAL_PROMPT": "0",
        "GCM_INTERACTIVE": "never",
        "GIT_SSH_COMMAND": f"{ssh} -o BatchMode=yes -o ConnectTimeout=15",
    }
    if rewrite is not None:
        # APPENDED, NOT REPLACED: the environment may already carry GIT_CONFIG_COUNT entries.
        # The whole recorded URL maps to the whole transport URL; longest match wins (D.64).
        index = int(os.environ.get("GIT_CONFIG_COUNT", "0"))
        replacement, original = rewrite
        wanted[f"GIT_CONFIG_KEY_{index}"] = f"url.{replacement}.insteadOf"
        wanted[f"GIT_CONFIG_VALUE_{index}"] = original
        wanted["GIT_CONFIG_COUNT"] = str(index + 1)
    saved = {key: os.environ.get(key) for key in wanted}
    os.environ.update(wanted)
    # BOTH ENVIRONMENTS (D.247). Copier runs git through plumbum, whose local.env
    # is a copy of os.environ taken when copier is imported, so a value set only
    # in os.environ never reached the clone: it went over HTTPS and prompted.
    try:
        with local.env(**wanted):
            yield
    finally:
        for key, value in saved.items():
            if value is None:
                os.environ.pop(key, None)
            else:
                os.environ[key] = value


def request(destination: Path, ref: str, *, root: Path = ROOT) -> TemplateRequest:
    """The request as observed: where it would land, and what is already there."""
    target = destination.expanduser().resolve()
    exists = target.exists()
    declared = load(root).repository
    return TemplateRequest(
        source=f"{declared}.git",
        transport=_ssh(declared),
        ref=ref,
        destination=str(target),
        destination_exists=exists,
        destination_empty=not exists or (target.is_dir() and not any(target.iterdir())),
        inside_source=target.is_relative_to(root.resolve()),
    )


def main(argv: Sequence[str] | None = None) -> int:
    """template:new <destination> <ref> -- generate, pinned, or refuse with every reason."""
    args = list(sys.argv[1:] if argv is None else argv)
    if len(args) != 2:
        usage = "usage: mise run run template:new <destination> <ref>"
        stopped = halted(SUBJECT, ENTRYPOINT, POLICY, usage)
        return enforce(announce(COMMAND, stopped, "usage", usage, {}))
    made = request(Path(args[0]), args[1])
    observed = made.model_dump(mode="json")
    found = evaluate(made, SUBJECT, POLICY, ENTRYPOINT)
    decision = decide(found)
    if decision.action != "proceed":
        code = refusal_code(decision, "template_refused")
        return enforce(announce(COMMAND, decision, code, reasons(found), observed))
    # REACHED ONLY WHEN THE POLICY ALLOWS: a pinned sha, a new place, outside this repo.
    try:
        with _non_interactive((made.transport, made.source)):
            run_copy(made.source, made.destination, vcs_ref=made.ref, defaults=True, quiet=True)
    except Exception as problem:
        reason = (str(problem).strip() or type(problem).__name__).splitlines()[0]
        stopped = halted(SUBJECT, ENTRYPOINT, POLICY, reason)
        return enforce(announce(COMMAND, stopped, "generation_failed", reason, observed))
    message = f"{made.destination} from {made.source} via {made.transport} at {made.ref}"
    return enforce(announce(COMMAND, decision, "project_generated", message, observed))


if __name__ == "__main__":
    sys.exit(main())
